    root.properties.insert(property_id::WIDTH, 100.0f32.to_bits());
    root.properties.insert(property_id::HEIGHT, 24.0f32.to_bits());
    root.properties.insert(property_id::ALIGNMENT, 0.0f32.to_bits());
